<script setup lang="ts">
import {ref,computed} from 'vue';import {useRoute} from 'vue-router';import {labs} from './data';
const id=String(useRoute().params.id);const lab=labs.find(x=>x.id===id);const a=ref(5),b=ref(4),c=ref(2),heads=ref(0),total=ref(0),reveal=ref(false);
const clamp=(n:number,min:number,max:number)=>Math.max(min,Math.min(max,n));
const angle=(p:number[],q:number[],r:number[])=>{const u=[p[0]-q[0],p[1]-q[1]],v=[r[0]-q[0],r[1]-q[1]];return Math.acos(clamp((u[0]*v[0]+u[1]*v[1])/(Math.hypot(...u)*Math.hypot(...v)),-1,1))*180/Math.PI};
const points=computed(()=>[[70,220],[70+a.value*24,220],[30+c.value*27,220-b.value*24]]);
const angles=computed(()=>points.value.map((p,i)=>angle(points.value[(i+1)%3],p,points.value[(i+2)%3])));
function toss(n:number){for(let i=0;i<n;i++){total.value++;if(Math.random()<.5)heads.value++}}
function reset(){a.value=5;b.value=4;c.value=2;heads.value=0;total.value=0;reveal.value=false}
function drag(e:PointerEvent){const svg=(e.currentTarget as SVGElement).ownerSVGElement!;const rect=svg.getBoundingClientRect();c.value=clamp(Math.round(((e.clientX-rect.left)*360/rect.width-30)/27),0,11)}
</script><template><RouterLink to="/">← 返回实验室</RouterLink><template v-if="lab"><h1>{{lab.title}}</h1><p>{{lab.desc}}</p><div class="workspace"><section class="board"><svg viewBox="0 0 360 260" v-if="id!=='chance'"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#e4e9e5"/></pattern></defs><rect width="360" height="260" fill="url(#grid)"/>
<g v-if="id==='curtain'||id==='angle'"><path :d="'M10 '+points[2][1]+' H350 M10 220 H350'" stroke="#9aa9a3" stroke-dasharray="5 5"/><polygon :points="points.map(p=>p.join(',')).join(' ')" fill="#79c6b3" fill-opacity=".5" stroke="#267c72" stroke-width="2"/><path :d="'M'+points[2][0]+' '+points[2][1]+' V220'" stroke="#e09943" stroke-dasharray="5 4"/><circle :cx="points[2][0]" :cy="points[2][1]" r="10" fill="#267c72" style="touch-action:none;cursor:grab" @pointerdown="(e)=>{(e.currentTarget as Element).setPointerCapture(e.pointerId);drag(e)}" @pointermove="(e)=>{if((e.currentTarget as Element).hasPointerCapture(e.pointerId))drag(e)}"/><text v-if="id==='angle'" v-for="(p,i) in points" :x="p[0]" :y="p[1]+(i===2?-15:20)" text-anchor="middle" font-size="12">{{angles[i].toFixed(1)}}°</text></g>
<g v-else-if="id==='perimeter'"><rect :x="180-a*12" :y="130-(10-a)*12" :width="a*24" :height="(10-a)*24" fill="#f1c879" stroke="#ac7833" stroke-width="2"/><text x="180" y="135" text-anchor="middle">{{a*(10-a)}} cm²</text></g>
<g v-else-if="id==='fraction'"><rect v-for="i in b" :x="20+(i-1)*320/b" y="85" :width="320/b" height="80" :fill="i<=Math.min(a,b)?'#79c6b3':'#fff'" stroke="#267c72"/><text x="180" y="195" text-anchor="middle">{{Math.min(a,b)}} / {{b}}</text></g>
<g v-else-if="id==='array'"><circle v-for="i in a*b" :cx="55+((i-1)%a)*29" :cy="35+Math.floor((i-1)/a)*27" r="9" :fill="(i-1)%a<Math.min(c,a)?'#69ae9b':'#e9b45e'"/></g></svg>
<div v-else class="coin"><div>◉</div><h2>{{heads}} / {{total}}</h2><p>正面比例：{{total?(heads/total*100).toFixed(1):0}}%</p><progress :value="heads" :max="total||1"/></div>
<div class="metrics" v-if="id==='curtain'">底 {{a}} · 高 {{b}} · 面积 {{a*b/2}}</div><div class="metrics" v-if="id==='angle'">内角和 {{angles.reduce((s,x)=>s+x,0).toFixed(1)}}°</div><div class="metrics" v-if="id==='perimeter'">周长 20 cm · 面积 {{a*(10-a)}} cm²</div><div class="metrics" v-if="id==='array'">{{b}} × {{a}} = {{b}} × {{Math.min(c,a)}} + {{b}} × {{a-Math.min(c,a)}} = {{a*b}}</div></section>
<aside><h2>动手探索</h2><template v-if="id==='chance'"><button @click="toss(1)">抛一次</button><button @click="toss(100)">抛100次</button></template><template v-else><label>{{id==='fraction'?'选中份数':id==='array'?'列数':'底边 / 长'}} {{a}}<input type="range" min="1" :max="id==='fraction'?b:9" v-model.number="a"/></label><label v-if="id!=='perimeter'">{{id==='fraction'?'总份数':id==='array'?'行数':'高度'}} {{b}}<input type="range" min="1" max="8" v-model.number="b" @input="id==='fraction'&&(a=Math.min(a,b))"/></label><label v-if="['curtain','angle','array'].includes(id)"> {{id==='array'?'分割位置':'顶点位置'}} {{c}}<input type="range" min="0" :max="id==='array'?a:11" v-model.number="c"/></label></template><button class="secondary" @click="reset">重置实验</button><h3>想一想</h3><p>{{lab.question}}</p><button @click="reveal=!reveal">{{reveal?'隐藏规律':'查看规律'}}</button><p v-if="reveal">{{lab.rule}}</p><h3>举一反三</h3><p>{{lab.next}}</p></aside></div><RouterLink to="/atlas">探索关联知识 →</RouterLink></template><p v-else>未找到实验。</p></template>